<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
$counts = ['menu' => 0, 'new' => 0, 'subscribers' => 0, 'recommendations' => 0, 'orders' => 0, 'customers' => 0];
$recent = [];
try {
    $counts['menu'] = (int)db()->query('SELECT COUNT(*) FROM menu_items WHERE is_available = 1')->fetchColumn();
    $counts['new'] = (int)db()->query("SELECT COUNT(*) FROM contact_messages WHERE status = 'new'")->fetchColumn();
    $counts['subscribers'] = (int)db()->query('SELECT COUNT(*) FROM newsletter_subscribers WHERE is_active = 1')->fetchColumn();
    $counts['recommendations'] = (int)db()->query('SELECT COUNT(*) FROM coffee_recommendations')->fetchColumn();
    $counts['orders'] = (int)db()->query("SELECT COUNT(*) FROM orders WHERE status IN ('pending','confirmed','preparing','ready','out_for_delivery')")->fetchColumn();
    $counts['customers'] = (int)db()->query('SELECT COUNT(*) FROM customers')->fetchColumn();
    $recent = db()->query('SELECT id,name,email,subject,status,created_at FROM contact_messages ORDER BY created_at DESC LIMIT 6')->fetchAll();
} catch (Throwable $exception) { error_log('Dashboard query failed: ' . $exception->getMessage()); }
$adminPageTitle = 'Overview'; require __DIR__ . '/includes/header.php';
