ll></td><td><?= e($message['subject']) ?></td><td><?= e(date('M j, Y', strtotime($message['created_at']))) ?></td><td><span class="status-pill <?= e($message['status']) ?>"><?= e($message['status']) ?></span></td><td><a class="table-action" href="<?= e(base_url('admin/messages.php?id=' . $message['id'])) ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php require __DIR__ . '/includes/footer.php'; ?>
